output reg[31:0] rdata2; 
integer i;
reg [31:0] memory [31:0]; 
always @ (posedge clk or negedge rst)
begin
	if (rst==0) 
	begin
		for (i=0;i<32;i=i+1) 
			memory[i] <= 0;
		rdata1 <= 0;
		rdata2 <= 0;
	end
	else
	begin
		rdata1<=memory[rdsel1];
		rdata2<=memory[rdsel2];
		if (wenable == 1)
		begin
			memory[wtsel] <= wtdata;
		end
	end 
end
endmodule

