description:
Implement the Verilog module based on the following description.
We want to create a D flip-flop that:

// (1) takes a data input 'd',
// (2) has a clock input 'clk',
// (3) outputs 'q' which holds the value of 'd' on the rising edge of 'clk'.

module d_flip_flop(
    input wire d,
    input wire clk,
    output reg q
);

code:
module d_flip_flop(
    input wire d,
    input wire clk,
    output reg q
);

    always @(posedge clk) begin
        q <= d;
    end

endmodule

